mapper.select:
select 
  from wms_loc_check c join mst_equip_hier n on n.node_id = c.node_id
 where c.check_id = #{id}

mapper.sql:
 from wms_loc_check c join mst_equip_hier n on n.node_id = c.node_id
where c.plant_cd = #{plantCd} and c.check_date between #{from} and #{to}
  and c.status = #{status}
  and exists (select 1 from wms_loc_check_line l
                                 where l.check_id = c.check_id and l.result <> 'OK' and l.review_action is null)

mapper.select:
select (select count(*) from wms_loc_check c where c.status = 'DONE' and c.check_date between #{from} and #{to}
           and c.plant_cd = #{plantCd}) as done_cnt,
       (select count(*) from wms_loc_check c where c.status = 'DONE' and c.accurate_yn = 'Y' and c.check_date between #{from} and #{to}
           and c.plant_cd = #{plantCd}) as accurate_cnt,
       (select count(*) from wms_loc_check_line l join wms_loc_check c on c.check_id = l.check_id
         where l.result <> 'OK' and l.review_action is null and c.plant_cd = #{plantCd}) as open_cnt
